// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read yesterday's POs": "in1_ReadyesterdaysPOs", "Read approved requests": "in2_Readapprovedrequests"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read approved requests";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"exception_body": JSON.stringify({ recipe: 'R11.2', item: out.po, reason: 'PO without approved request', detail: 'PO ' + out.po + ' for ' + out.amount + ' has no approved request', owner: $('Config').first().json.backstop_reviewer }), "message": JSON.stringify({ to: $('Config').first().json.backstop_reviewer, subject: 'PO without an approved request', text: 'PO ' + out.po + ' for ' + out.amount })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 11: any PO over the limit with no approved request goes to the finance reviewer.
const cfg = $('Config').first().json;
const pos = $('Read yesterday\'s POs').first().json.items || [];
const approved = new Set(($('Read approved requests').first().json.items || []).map(r => r.id));
const orphans = pos.filter(p => Number(p.amount) > cfg.no_po_limit && !approved.has(p.request_id));
return orphans.map(p => ({ json: { po: p.id, amount: p.amount, request_id: p.request_id || null } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
